  await block('Orange_mission_badge',[1.85,2.7,.18],[-.15,4.7,3.79],M.accent,root,.14);
  const insignia=group('mission_insignia',[-.15,4.7,3.90]);
  const orbit=new THREE.Mesh(new THREE.TorusGeometry(.43,.025,4,20),M.panel);orbit.scale.set(1,.66,1);orbit.rotation.z=.6;insignia.add(orbit);orbit.name='Generic_orbital_ring';
  strut('Orbit_slash',[-.50,-.42,.02],[.48,.45,.02],.024,insignia,M.panel);
  await block('Badge_lower_label',[.7,.08,.035],[-.15,3.72,3.90],M.panel);
  // Long low wing, connected through pressure collars; front windows face +X.
