  const wingRoof=group('wing_roof',[0,0,0],wing);
  await block('Wing_foundation',[4.95,.48,13.7],[.0,.24,-9.85],M.panelGray,wing,.16);
  await block('Wing_pressure_shell',[4.7,3.65,13.15],[.0,2.35,-9.65],M.panel,wing,.55);
  await block('Wing_roof_long_cap',[4.95,.28,13.4],[0,4.25,-9.65],M.panel,wingRoof,.12);
  const wingCross=oct(4.95,4.05,.64),wingHole=oct(4.38,3.48,.48);
  for(const z of [-3.6,-7.1,-10.6,-14.1,-16.05]) {
    // Extrusion along Z for the corridor's wraparound cross-frame.
    const geo=extrusion(wingCross,.38,wingHole);geo.rotateY(Math.PI/2);
    createPart('Wing_pressure_collar_'+z,geo,M.panelGray,{position:[0,2.35,z],parent:wing});
    for(const x of [-2.15,2.15]) await block('Wing_support_'+z+'_'+x,[.7,.68,.72],[x,.34,z],M.panelGray,wing);
  }
  for(const [i,z]of [-5.35,-8.85,-12.35,-15.2].entries()) {
    const w=i===3?1.0:2.55;
    await block('Window_slate_recess_'+i,[.20,1.05,w+.36],[2.38,2.65,z],M.panelGray,wing,.13);
    await block('Window_dark_gasket_'+i,[.12,.75,w+.13],[2.53,2.65,z],M.trim,wing,.10);
    await block('Window_amber_pane_'+i,[.07,.49,w],[2.615,2.65,z],M.glowWarm,wing,.075);
    for(const off of i===3?[]:[-.43,.43]) await block('Window_mullion_'+i+'_'+off,[.09,.60,.085],[2.67,2.65,z+off],M.panelGray,wing,.02);
  }
  for(const z of [-5.3,-12.3]) {
    await block('Wing_orange_service_plate_'+z,[.1,.50,.50],[2.39,1.35,z],M.accent,wing,.07);
    await block('Wing_small_amber_marker_'+z,[.05,.15,.20],[2.47,1.35,z],M.glowWarm,wing,.025);
  }
  // Rooftop service volumes support towers on actual roof contact plates.
