  await block('Dish_pivot_mount',[1.25,.38,1.25],[0,1.82,0],M.panelGray,support);
  strut('Dish_elevation_stem',[0,1.85,0],[-.08,3.23,0],.105,support);
  const dish=group('dish',[0,3.30,0],support);dish.rotation.z=-.83;dish.rotation.y=-.18;
  // Closed parabolic shell with paired front/back skins and a faceted rim.
