  const feed=[0,2.1,0];
  for(const angle of [0,2.0944,4.1888])strut('Dish_feed_arm_'+angle,[R*.87*Math.cos(angle),R*R*.87*.87/6.6,R*.87*Math.sin(angle)],feed,.027,dish,M.panelGray);
  await block('Dish_receiver_orange',[.24,.32,.24],feed,M.accent,dish,.06);
  const anchor=group('info_anchor',[5.5,4.8,0]);
  anchor.userData.role='module-info';
  group('entrance_anchor',[7.9,0,-.1]);
  group('interior_anchor',[0,1.15,0]);
  // Match the approved hero's handedness: connected wing on the entrance's left.
  root.scale.z = -1;
  defineBudget({ triangles: BUDGETS.building },root);
